css:
.print-format-container {
  font-family: Arial, sans-serif;
  font-size: 12px;
  margin: 20px;
}
.header {
  display: flex;
  align-items: center;
  margin-bottom: 10px;
}
.left-header {
  width: 40%;
  text-align: center;
}
.right-header {
  width: 60%;
  text-align: left;
}
.logo {
  margin-right: 20px;
}
.logo img {
  height: 120px;
}
.datos-generales {
  margin-bottom: 10px;
  border-bottom: 2px solid black;
  border-top: 2px solid black;
}

.info-complement {
  display: flex;
  justify-content: space-evenly;
  margin-top: 10px;
  margin-bottom: 10px;
}
.datos-medicamentos{
  margin-top: 20px;
}
.lefy {
  text-align: left;
  width: 50%;
}
.right {
  text-align: left;
  width: 50%;
}
.footer {
  position: relative;
  bottom: 0;
  left: 0;
  width: 100%;  
  padding: 10px;
  margin-top: 10px;
}

.sign-section {
  text-align: left;  
}

.signature {
  display: inline-block;
  text-align: center;
}

table {
  width: 100%;
  border-collapse: collapse;
}
th, td {
  border: 1px solid black;
  text-align: left;
}
#table-info > tr > td{
    border: none !important;
}
table.table-compact td,
table.table-compact th {
    padding: 2px 4px !important;   /* súper compacto */
    margin: 0 !important;
    line-height: 1.1 !important;
    vertical-align: top;
}
.info-container{
  width: 100%;
  margin-bottom: 20px;
}
.examenes{
  border: 2px solid black;
  padding: 5px;
  border-radius: 2px;
}
.observaciones{
  text-align: left;
  padding: 5px;
}
.observaciones h4{
  text-align: center;
}
